<?php
class NtcreatorrewardsRewardsModuleFrontController extends ModuleFrontController
{
    public $auth=true; public $guestAllowed=false; public $ssl=true;
    public function postProcess(){if(Tools::isSubmit('submitNtcrHandle')){if(!Tools::getValue('token')||Tools::getValue('token')!==Tools::getToken(false))$this->errors[]='Güvenlik doğrulaması başarısız.';else try{$h=NtcrService::requestHandle((int)$this->context->customer->id,(int)$this->context->shop->id,Tools::getValue('tiktok_handle'));$this->success[]='@'.$h.' için eşleştirme talebiniz alındı.';}catch(Exception $e){$this->errors[]=$e->getMessage();}}if(Tools::isSubmit('submitNtcrRequest')){if(Tools::getValue('token')!==Tools::getToken(false))$this->errors[]='Güvenlik doğrulaması başarısız.';else try{$p=NtcrService::publisherForCustomer((int)$this->context->customer->id,(int)$this->context->shop->id);$no=NtcrRequestService::create((int)$p['id_publisher'],Tools::getValue('request_type'),array('id_catalog'=>Tools::getValue('id_catalog'),'delivery'=>Tools::getValue('delivery'),'scheduled_local'=>Tools::getValue('scheduled_local'),'amount_try'=>Tools::getValue('amount_try'),'iban'=>Tools::getValue('iban'),'account_owner'=>Tools::getValue('account_owner')),(int)$this->context->shop->id);$this->success[]='Talebiniz oluşturuldu: '.$no;}catch(Exception $e){$this->errors[]=$e->getMessage();}}parent::postProcess();}
    public function initContent(){parent::initContent();$p=NtcrService::publisherForCustomer((int)$this->context->customer->id,(int)$this->context->shop->id);$w=$p?Db::getInstance()->getRow('SELECT * FROM `'._DB_PREFIX_.'ntcr_wallet` WHERE id_publisher='.(int)$p['id_publisher']):null;$perf=$p?Db::getInstance()->executeS('SELECT r.period,r.diamonds,r.valid_days,r.live_hours,r.target_points,b.date_approved FROM `'._DB_PREFIX_.'ntcr_source_row` r INNER JOIN `'._DB_PREFIX_.'ntcr_batch` b ON b.id_batch=r.id_batch WHERE r.id_publisher='.(int)$p['id_publisher']." AND b.status='approved' ORDER BY r.period DESC LIMIT 12"):array();$ledger=$p?Db::getInstance()->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_ledger` WHERE id_publisher='.(int)$p['id_publisher'].' ORDER BY id_ledger DESC LIMIT 100'):array();$requests=$p?Db::getInstance()->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_request` WHERE id_publisher='.(int)$p['id_publisher'].' ORDER BY id_request DESC LIMIT 100'):array();$catalog=Db::getInstance()->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_catalog` WHERE id_shop='.(int)$this->context->shop->id.' AND active=1 ORDER BY type,position,id_catalog');$this->context->smarty->assign(array('ntcr_publisher'=>$p,'ntcr_wallet'=>$w,'ntcr_performance'=>$perf,'ntcr_ledger'=>$ledger,'ntcr_requests'=>$requests,'ntcr_catalog'=>$catalog,'ntcr_token'=>Tools::getToken(false)));$this->setTemplate('module:ntcreatorrewards/views/templates/front/rewards.tpl');}
}
